describe("doctests of sympy.abc", () => {
  it("S(\"Q & C\", locals=_clash1)", () => {
    const [O, Q, N, I, E, S] = symbols('O Q N I E S');
    expect(sympyStr(parse('Q & C', { symbols: { O: O, Q: Q, N: N, I: I, E: E, S: S } }))).toBe('C & Q');
  });
  it("S('pi(x)', locals=_clash2)", () => {
    const [beta, zeta, gamma, pi] = symbols('beta zeta gamma pi');
    expect(sympyStr(parse('pi(x)', { symbols: { beta: beta, zeta: zeta, gamma: gamma, pi: pi } }))).toBe('pi(x)');
  });
  it("S('pi(C, Q)', locals=_clash)", () => {
    const [O, Q, N, I, E, S, beta, zeta, gamma, pi] = symbols('O Q N I E S beta zeta gamma pi');
    expect(sympyStr(parse('pi(C, Q)', { symbols: { O: O, Q: Q, N: N, I: I, E: E, S: S, beta: beta, zeta: zeta, gamma: gamma, pi: pi } }))).toBe('pi(C, Q)');
  });
});

